from pathlib import Path
p=Path('work/king-street/app/king-pilot.tsx');s=p.read_text()
s=s.replace("ArrowDownToLine,ArrowUpRight", "ArrowDownToLine,ArrowUpRight,ChevronRight,Sun,CloudSun,X")
s=s.replace("export type World={center:","export type World={streetViews?:{position:number[];lookAt:number[];label:string}[];center:")
s=s.replace("select:(id:string)=>void}|null>","select:(id:string)=>void;lighting:(overcast:boolean)=>void;nextStreet:()=>void}|null>")
s=s.replace("[mode,setMode]=useState('orbit')","[mode,setMode]=useState('street')")
s=s.replace("const [download,setDownload]", "const [panel,setPanel]=useState(false),[overcast,setOvercast]=useState(false);\n const [download,setDownload]")
s=s.replace("SAN FRANCISCO / PILOT 02", "SAN FRANCISCO / PILOT 03").replace("DETAIL PASS", "STREET STUDY")
s=s.replace('<span className="view-divider"/>', '<span className="view-divider"/><Button variant="ghost" size="icon" title={overcast?"Switch to afternoon sun":"Switch to soft daylight"} aria-label={overcast?"Afternoon sun":"Soft daylight"} onClick={()=>{setOvercast(!overcast);api.current?.lighting(!overcast)}}>{overcast?<CloudSun/>:<Sun/>}</Button>')
s=s.replace('<aside className="inspector">','<Button className="inspect-toggle" variant="outline" onClick={()=>setPanel(!panel)} aria-expanded={panel}>{panel?<X/>:<Layers3/>}{panel?"Close details":"Scene details"}</Button>{mode===\'street\'&&<Button className="next-street" variant="outline" onClick={()=>api.current?.nextStreet()}>Next street view<ChevronRight/></Button>}<aside className={`inspector ${panel?\'is-open\':\'is-closed\'}`}>')
s=s.replace('PILOT 02 / EVIDENCE','PILOT 03 / EVIDENCE')
s=s.replace('Recessed windows, shared scanned materials, and street components generated from a reusable schema. Most facades still need direct observations.','Facade layouts fitted from dated image observations, with repeated patterns completed within each observed wall region. Unseen walls still use priors. Daylight and contact shading are approximations, not a baked lighting solution.')
s=s.replace('Independent facade measurements, complete imagery coverage, sculpted ornament, calibrated curbs and paint, and image-verified sign placement. Scanned material texture is not proof of the material on a particular wall. The accuracy gate remains open.','More independent views, calibrated depths, sculpted ornament, verified curb and paint geometry, and image-verified sign placement. Observed layout and inferred completion are distinct. This scene has not passed a 1:1 street-accuracy test.')
s=s.replace('W A S D to move · drag to look · Shift to move faster','Driver height 1.25 m · W A S D to move · drag to look')
p.write_text(s)
p=Path('work/king-street/app/globals.css');s=p.read_text();s+='\n/* Street inspection keeps the road and facades unobstructed. */\n.inspector.is-closed{display:none}.inspect-toggle{position:absolute;top:98px;left:24px;background:#f6f9faec;z-index:2}.inspector.is-open{top:148px;max-height:calc(100dvh - 205px);overflow:auto}.next-street{position:absolute;bottom:84px;left:26px;background:#f6f9faed}.controls-help{background:#f6f9fadb;border-radius:6px;padding:7px 10px;color:#233e4c}.eyebrow{font-size:12px}.layer-row{font-size:14px}.source-lines b{font-size:12px}.attribution{font-size:12px}\n@media(max-width:640px){.inspect-toggle{top:auto;bottom:48px;left:15px;height:34px}.next-street{left:auto;right:15px;bottom:48px;height:34px}.inspector.is-open{top:135px;bottom:100px;max-height:calc(100dvh - 250px)}.viewbar button{padding-inline:9px}.controls-help{display:none}}\n';p.write_text(s)
